#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/kotlin/tasks/code-format-ktlint.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check or format the Kotlin files with ktlint"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="format every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="apply fixes"
# USAGE arg "[files]" var=#true help="the files to format; only the .kt and .kts files are used; the default is the uncommitted files"
# FILES include="*.kt *.kts" exclude="**/generated/**"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def flag(name):
  """Whether mise gives the flag name as true."""
  return os.environ.get(f"usage_{name}", "false") == "true"


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def main():
  # Shipped with the kotlin tool. Without ktlint, the task does not apply and
  # prints nothing.
  if not helpers.has_tool("ktlint"):
    sys.exit(0)
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # code:format passes its flags and files to each code:format:* task. The
  # list comes from gate_files (the # FILES header above). An empty list:
  # nothing to do.
  args = [f"--{name}" for name in ("all", "debug", "fix") if flag(name)]
  listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
  try:
    with open(listing, "rb") as data:
      paths = data.read()
    if not paths:
      sys.exit(0)

    ktlint_args = ["--relative", "--editorconfig=.config/ktlint.editorconfig"]
    if flag("debug"):
      ktlint_args.append("--log-level=debug")
    if flag("fix"):
      ktlint_args.append("--format")

    helpers.print_header("Formatting the Kotlin files with ktlint ...")
    # Without --fix, the check is the lint of ktlint: it reports each file that
    # --format changes, and each problem that --format cannot fix.
    result = subprocess.run(
      ["xargs", "-0", "mise", "x", "--", "ktlint", *ktlint_args], input=paths.replace(b"\n", b"\0"), check=False
    )
    sys.exit(exit_code(result.returncode))
  finally:
    os.remove(listing)


main()
